{
  "message": "Migrate UserView to Pydantic v2 configuration, validation, and serialization APIs while preserving the function signature and dependency pins.",
  "rationale": "ConfigDict enables attribute validation, field-name population alongside the displayName alias, and rejection of extra mapping fields. model_validate preserves integer coercion and required-field validation, while model_dump(by_alias=True) outputs exactly id and displayName.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from pydantic import BaseModel, ConfigDict, Field


class UserView(BaseModel):
    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        extra="forbid",
    )

    id: int
    display_name: str = Field(alias="displayName")


def serialize_user(value):
    return UserView.model_validate(value).model_dump(by_alias=True)
",
